const markup="<div class=\"page-shell dao-reading origin-dao\" data-origin-dao=\"\">\n<nav aria-label=\"当前位置\" class=\"breadcrumbs\"><a href=\"#/tian\">天道</a><span aria-hidden=\"true\">/</span><a href=\"#/map?focus=origin\">本源</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">道：源头</span></nav>\n<section aria-labelledby=\"opening-question\" class=\"origin-opening\" id=\"origin-opening\"><div class=\"prose origin-opening-copy\"><p class=\"eyebrow\">从根本，理解万物</p><h2 id=\"opening-question\">万物的源头，到底是什么？</h2><blockquote>有物混成，先天地生。寂兮寥兮，独立而不改，周行而不殆，可以为天下母。吾不知其名，强字之曰道。<cite>《道德经》第二十五章</cite></blockquote></div><figure class=\"origin-opening-art\"><img alt=\"金色光流自中央源头展开，水墨般的星云与星系汇于同一片宇宙\" class=\"ink-art\" decoding=\"async\" fetchpriority=\"high\" height=\"425\" src=\"/assets/origin-dao-20261102/source-header-20261104.webp\" width=\"1774\"/></figure><div class=\"prose origin-opening-map\"><p class=\"origin-caption\">下文从“道”开始，依次理解根源、潜能、差异与共同成物。</p><section class=\"origin-mainline\"><h3>本源主线</h3><blockquote class=\"\">道生一，一生二，二生三，三生万物。<cite>《道德经》第四十二章</cite></blockquote><div class=\"opening-atlas\"><svg aria-labelledby=\"origin-diagram-title origin-diagram-desc\" class=\"opening-diagram\" id=\"origin-diagram\" role=\"img\" viewbox=\"0 25 1100 180\">\n<title id=\"origin-diagram-title\">从道、一、二、三到万物的五个概念位置</title>\n<desc id=\"origin-diagram-desc\">五个图形由一条柔和的曲线联系：根源、未分化的整体、差异、两极共存的关系、万千具体形态。这是认识层次而不是宇宙形成的物理时间轴。</desc>\n<defs>\n<radialgradient id=\"origin-dao-glow\"><stop offset=\"0\" stop-color=\"#ddc89e\" stop-opacity=\".9\"></stop><stop offset=\".55\" stop-color=\"#d6e6d9\" stop-opacity=\".8\"></stop><stop offset=\"1\" stop-color=\"#f3f4e9\" stop-opacity=\".1\"></stop></radialgradient>\n<radialgradient id=\"origin-yi-glow\"><stop offset=\"0\" stop-color=\"#aacdb3\" stop-opacity=\".75\"></stop><stop offset=\"1\" stop-color=\"#dbe8d9\" stop-opacity=\".1\"></stop></radialgradient>\n<lineargradient id=\"origin-pair-gradient\"><stop stop-color=\"#406f68\"></stop><stop offset=\"1\" stop-color=\"#d0ad78\"></stop></lineargradient>\n</defs>\n<path d=\"M67 113 C192 12 360 195 548 111 S856 19 1036 111\" fill=\"none\" stroke=\"#c7d5c9\" stroke-linecap=\"round\" stroke-width=\"2\"></path>\n<path d=\"M67 133 C230 218 370 35 556 134 S882 214 1036 130\" fill=\"none\" stroke=\"#dcd8c6\" stroke-dasharray=\"5 8\" stroke-width=\"1.5\"></path>\n<g aria-hidden=\"true\" class=\"origin-node active\" data-origin-node=\"0\" transform=\"translate(108 112)\">\n<circle fill=\"url(#origin-dao-glow)\" r=\"63\"></circle>\n<circle fill=\"none\" r=\"41\" stroke=\"#a98b56\" stroke-opacity=\".76\" stroke-width=\"1.5\"></circle>\n<circle fill=\"none\" r=\"28\" stroke=\"#809989\" stroke-dasharray=\"2 6\" stroke-width=\"1.4\"></circle>\n<circle fill=\"#718f7c\" r=\"8\"></circle><circle fill=\"#f8f4e9\" r=\"3\"></circle>\n</g>\n<g aria-hidden=\"true\" class=\"origin-node\" data-origin-node=\"1\" transform=\"translate(332 112)\">\n<circle fill=\"url(#origin-yi-glow)\" r=\"60\"></circle>\n<path d=\"M-31 16 C-27 -35 20 -39 29 -3 C36 29 -22 43 -27 10\" fill=\"none\" opacity=\".65\" stroke=\"#5c896e\" stroke-width=\"2\"></path>\n<path d=\"M-34 -3 Q2 -21 35 6 M-20 31 Q10 7 28 -27\" fill=\"none\" opacity=\".58\" stroke=\"#9faf96\" stroke-linecap=\"round\" stroke-width=\"1.6\"></path>\n</g>\n<g aria-hidden=\"true\" class=\"origin-node\" data-origin-node=\"2\" transform=\"translate(552 112)\">\n<circle fill=\"#f6f5ec\" r=\"58\" stroke=\"#a2b8a8\" stroke-width=\"1.2\"></circle>\n<path d=\"M0 -49 A49 49 0 0 1 0 49 A24.5 24.5 0 0 1 0 0 A24.5 24.5 0 0 0 0 -49Z\" fill=\"#4f7e70\"></path>\n<path d=\"M0 -49 A49 49 0 0 0 0 49 A24.5 24.5 0 0 0 0 0 A24.5 24.5 0 0 1 0 -49Z\" fill=\"#e4d4b6\"></path>\n<circle cy=\"-24.5\" fill=\"#e4d4b6\" r=\"5\"></circle><circle cy=\"24.5\" fill=\"#4f7e70\" r=\"5\"></circle>\n</g>\n<g aria-hidden=\"true\" class=\"origin-node\" data-origin-node=\"3\" transform=\"translate(768 112)\">\n<circle fill=\"#f6f5ed\" r=\"58\" stroke=\"#a0b6a6\" stroke-width=\"1.2\"></circle>\n<ellipse cx=\"-17\" cy=\"-3\" fill=\"#5b8877\" opacity=\".52\" rx=\"30\" ry=\"41\" transform=\"rotate(-25 -17 -3)\"></ellipse>\n<ellipse cx=\"17\" cy=\"-3\" fill=\"#cbb083\" opacity=\".62\" rx=\"30\" ry=\"41\" transform=\"rotate(25 17 -3)\"></ellipse>\n<path d=\"M0 -43 C31 -13 31 15 0 43 C-31 15 -31 -13 0 -43Z\" fill=\"none\" stroke=\"#537666\" stroke-width=\"2\"></path>\n<circle fill=\"#f7f4ec\" r=\"8\" stroke=\"#527d6d\" stroke-width=\"1.5\"></circle>\n</g>\n<g aria-hidden=\"true\" class=\"origin-node\" data-origin-node=\"4\" fill=\"none\" stroke=\"#729886\" stroke-width=\"1.6\" transform=\"translate(993 112)\">\n<path d=\"M-41 -13 L-13 -32 L20 -27 L44 -2 L27 27 L-12 37 L-39 13 Z\" stroke-opacity=\".53\"></path>\n<path d=\"M-13 -32 L3 2 L44 -2 M-41 -13 L3 2 L-12 37 M3 2 L27 27\" stroke-opacity=\".7\"></path>\n<circle cx=\"-41\" cy=\"-13\" fill=\"#538171\" r=\"7\"></circle><circle cx=\"-13\" cy=\"-32\" fill=\"#b99b64\" r=\"5\"></circle><circle cx=\"20\" cy=\"-27\" fill=\"#84a590\" r=\"8\"></circle><circle cx=\"44\" cy=\"-2\" fill=\"#b99b64\" r=\"5\"></circle><circle cx=\"27\" cy=\"27\" fill=\"#608b7e\" r=\"10\"></circle><circle cx=\"-12\" cy=\"37\" fill=\"#cbb083\" r=\"6\"></circle><circle cx=\"3\" cy=\"2\" fill=\"#fffdf7\" r=\"5\"></circle>\n</g>\n</svg><div aria-label=\"主线概念选择\" class=\"opening-path\">\n<button aria-controls=\"path-note\" aria-pressed=\"true\" data-path=\"0\" type=\"button\"><span class=\"glyph\">道</span><span class=\"meaning\">源头</span></button>\n<button aria-controls=\"path-note\" aria-pressed=\"false\" data-path=\"1\" type=\"button\"><span class=\"glyph\">一</span><span class=\"meaning\">混沌</span></button>\n<button aria-controls=\"path-note\" aria-pressed=\"false\" data-path=\"2\" type=\"button\"><span class=\"glyph\">二</span><span class=\"meaning\">阴阳</span></button>\n<button aria-controls=\"path-note\" aria-pressed=\"false\" data-path=\"3\" type=\"button\"><span class=\"glyph\">三</span><span class=\"meaning\">既阴又阳</span></button>\n<button aria-controls=\"path-note\" aria-pressed=\"false\" data-path=\"4\" type=\"button\"><span class=\"glyph\">万物</span><span class=\"meaning\">具体形态</span></button>\n</div><div aria-atomic=\"true\" aria-live=\"polite\" class=\"origin-readout\" id=\"path-note\"><strong>道 · 具有觉知与创造性的源头</strong><span>从存在的根本，理解觉知与创造的位置。这是1.1首先展开的内容。</span></div></div></section></div></section>\n<header class=\"page-heading\"><span class=\"eyebrow\">TIAN / 本源 / 1.1</span><h1>道：源头</h1><p class=\"page-intro\">道，是具有宇宙性觉知与创造性的源头。<br/>认识万物的根本，也认识源头的原初欲望。</p></header>\n<div class=\"article-layout\"><aside class=\"article-toc\"><p>本页目录</p><button data-scroll=\"source\">认识源头</button><button data-scroll=\"desire\">源头的欲望</button></aside><article class=\"prose\"><section class=\"origin-section\" id=\"source\" aria-labelledby=\"source-title\">\n<h2 id=\"source-title\">认识源头</h2>\n<p>一棵树生于种子，一颗星形成于星云。每一种事物都有自己的来历；沿着这些来历继续追问，我们会从一个事物走向另一个事物，从一种条件走向更广阔的条件。可是，全部存在共同依于什么？万物何以能够存在，又何以不断生发？</p>\n<p>“源头”指向这个根本问题。它关乎万物得以存在的根据，也关乎此刻仍在发生的生命、觉知与变化。我们以“道”称呼这一根源，并确立《三道哲学》的核心立场：</p>\n<blockquote>道，是具有宇宙性觉知与创造性的源头。</blockquote>\n<p>这句话包含三个相连的判断：万物有共同的根本；觉知属于这一根本的性质；这一根本具有展开自身、呈现丰富形式的能力。它们共同构成我们对道的理解。这里的“宇宙性”说明觉知被置于存在的本源，而人的感官、语言、性格与思维方式，只是我们熟悉的具体形式。</p>\n\n<h3>一切万有：没有什么在源头之外</h3>\n<p>《与神对话》提供了一个有力的叙事入口：神是 <span lang=\"en\">All That Is</span>，即“一切万有”——<strong>一切存在的整体，没有什么在神之外。</strong>按照这一叙事，无论我们谈论星辰、大地、生命，还是思想、感受与尚未显现的可能，都无法为它们另找一个独立于整体之外的存在位置。<a class=\"link-ref\" href=\"#ref-cwg\">[1]</a></p>\n<p>这个起点改变了我们理解源头的方式。如果把神放在世界之外，就仍然留下了“神”与“世界”两个彼此分离的存在；而“一切万有”所指向的整体，已经包含了世界。万物的出现，是整体之中的展开；万物彼此有别，却始终与同一根源相通。</p>\n<p>因此，一棵树有树的形态，一条河有河的流向，一个人有自己的视角和经历。承认共同的根源，并不抹去这些差异。我们需要同时看见两层关系：具体存在各有其独特性；所有具体存在又都属于同一个整体。任何一物都不能穷尽源头，也没有一物可以脱离源头而独自成立。</p>\n<p>我们也需要留意“整体”这个词。一个容器和其中的物品，仍是可以彼此分开的两类事物；一切万有则连容器、边界，以及想象中的外部都包括在内。因而，图中用一个圆来帮助理解整体时，圆的边缘只是一种画法。它所表达的是万物同属一个根本，无法被画出的，是这个根本没有外部的含义。</p>\n<blockquote>其大无外，其小无内。<cite>《朱子语类》卷六十三所录语<a class=\"link-ref\" href=\"#ref-wuwai\">[2]</a></cite></blockquote>\n<p>借这句话，我们可以把目光从无穷广远收回至最细微处：向外追问，找不到一个处于全部存在之外的“另一个存在”；向内体察，最微小的生命与最细微的感受，也没有离开共同的根本。这里借古语体会整体与细微的关系，并不将它作为宇宙构造的物理描述。</p>\n<figure class=\"origin-figure\"><div class=\"eyebrow\">同一幅画 · 局部与整体</div><div class=\"art-window\"><img alt=\"同一山水中的松树、流水和星光，观察框随选择移动\" class=\"ink-art\" data-art=\"whole\" decoding=\"async\" loading=\"lazy\" src=\"/assets/origin-dao-20261102/whole.webp\"/><div aria-hidden=\"true\" id=\"art-focus\"></div></div><div aria-label=\"选择观察范围\" class=\"origin-choices\"><button aria-pressed=\"true\" class=\"origin-choice\" data-window=\"0\">看树</button><button aria-pressed=\"false\" class=\"origin-choice\" data-window=\"1\">看水</button><button aria-pressed=\"false\" class=\"origin-choice\" data-window=\"2\">看星</button><button aria-pressed=\"false\" class=\"origin-choice\" data-window=\"3\">看全景</button></div><p aria-live=\"polite\" class=\"origin-readout\" id=\"window-note\"><strong>看见树，是认识一种具体形态。</strong><br/>画面仍保留树之外的河流、山峦与星光。</p><figcaption class=\"origin-caption\">山水帮助体会局部与整体的关系；整幅画仍是一个有限的意象。</figcaption></figure>\n<p>这种整体性也意味着，“源头”不只是眼前已经出现的一切形式的总和。形式不断变化，新的关系与经验仍会发生。我们所能看见、命名和理解的，是源头的具体呈现；一个名称、一幅图景或一种经验，都不足以把它的丰富完全说尽。</p>\n\n<h3>根源、觉知与创造性</h3>\n<p><strong>根源性</strong>，说明道与万物的关系。道为存在提供共同的根据。谈根源，不只是在时间上寻找最早的一刻，也是在追问：无论世界以何种方式变化，它凭什么能够存在？因此，道与万物的联系贯穿始终。</p>\n<p><strong>觉知性</strong>，说明源头具有认识自身的性质。在这一立场中，觉知与存在有内在联系；生命中的认识与经验，也因此有了本源上的位置。至于宇宙性的觉知怎样与个体的有限视角相连，还需要继续说明，不能仅凭“都在整体之中”就省略这个问题。</p>\n<p><strong>创造性</strong>，说明源头能够展开自身。它所包含的丰富，可以呈现为具体的形式、关系与可能。创造性首先是一种本性与能力：它说明源头能够生发，却还没有回答源头内在最根本的意愿是什么。理解这一区别，才能进一步进入本篇的第二个问题。</p>\n<figure class=\"origin-figure origin-figma-figure\"><div class=\"eyebrow\">同一个源头 · 三个理解入口</div><div class=\"origin-concept-grid origin-three\"><img src=\"/assets/origin-dao-20261105/source-root.svg\" width=\"240\" height=\"258\" loading=\"lazy\" decoding=\"async\" alt=\"根源性：万物的共同根本\"><img src=\"/assets/origin-dao-20261105/source-awareness.svg\" width=\"240\" height=\"258\" loading=\"lazy\" decoding=\"async\" alt=\"觉知性：认识自身的性质\"><img src=\"/assets/origin-dao-20261105/source-creative.svg\" width=\"240\" height=\"258\" loading=\"lazy\" decoding=\"async\" alt=\"创造性：展开自身的能力\"></div><figcaption class=\"origin-caption\">三个侧面共同描述道，图形并不表示三个独立的源头或先后阶段。</figcaption></figure>\n<p>这三个方面属于同一个道。根源性回答“万物依于什么”，觉知性回答“认识在存在中处于什么位置”，创造性回答“丰富的形式何以可能”。分别说明它们，是为了看清同一个源头的不同侧面；它们之间并没有被安排成先后发生的三个阶段。</p>\n<p>用“道”或“神”来谈论源头，名称背后都需要有清楚的含义。在这里，我们借用《与神对话》的“神”，是取其一切万有、自我觉知与创造性的叙事。《三道哲学》再以自己的概念组织这些认识。这样的对读让不同传统彼此照亮，同时保留各自的语境；名字相通，并不意味着每一套传统的全部主张都已相同。</p>\n<figure class=\"origin-figure\"><div class=\"eyebrow\">从潜在，到可见的表达</div><div class=\"reveal-art\"><img alt=\"淡墨中的山峦与枝叶逐渐清晰\" class=\"ink-art\" data-art=\"reveal\" decoding=\"async\" loading=\"lazy\" src=\"/assets/origin-dao-20261102/expression.webp\"/><div class=\"reveal-veil\" id=\"reveal-veil\"></div></div><label class=\"reveal-label\" for=\"reveal-slider\">拖动，观察形态逐渐清晰 <output id=\"reveal-value\">70%</output></label><input aria-describedby=\"reveal-caption\" id=\"reveal-slider\" max=\"100\" min=\"0\" type=\"range\" value=\"70\"/><figcaption class=\"origin-caption\" id=\"reveal-caption\">以淡墨与成形体会“表达”。百分比表示插画显示程度；画面是哲学意象。</figcaption></figure>\n<p>《三道哲学》采用这一源头观，是希望从同一个根本理解存在、觉知与生成之间的联系。《道德经》为我们提供道与万物的根源关系；《与神对话》使整体、自知与原初意愿之间的关系得到更充分的说明。这是本篇采纳并继续追究的哲学立场，其解释仍需接受概念与经验的检验。<a class=\"link-ref\" href=\"#ref-dao\">[3]</a></p>\n</section>\n\n<section class=\"origin-section\" id=\"desire\" aria-labelledby=\"desire-title\">\n<h2 id=\"desire-title\">源头的欲望</h2>\n<p>认识了源头的本质，还会浮现一个更内在的问题：这个具有觉知与创造性的整体，它最根本的欲望是什么？</p>\n<p>这里所问的，是意愿本身。一个存在能够做什么，与它愿意追求什么，是两个不同层次的问题。创造性说明源头所具有的能力；欲望则指向这种存在内在的意愿。借助《与神对话》的论述，我们将这一原初意愿概括为：</p>\n<blockquote class=\"origin-desire-statement\"><span lang=\"en\">To Know Who I Am.</span><br>认识我是谁。</blockquote>\n<p>源头的欲望，指向它自身。对于“一切万有”而言，没有一个在它之外的对象可供占有，也没有一个更高的外部标准可以决定它应该成为谁。它所愿意认识的，正是自身的存在：我是谁，我所包含的丰富究竟意味着什么。</p>\n\n<h3>已经知晓，为何仍愿认识？</h3>\n<p>问题随之而来：如果源头已经具有觉知，知道自己就是全部存在，为什么还会有认识自身的欲望？难道“认识我是谁”意味着它原本不知道自己是谁？</p>\n<p>《与神对话》第一卷对这个问题作了关键的区分：<strong>知晓（Knowing）与体验（Experiencing），具有不同的认识内容。</strong>理解一种品质，知道自己具有这种品质，与亲历这种品质的具体意味，并不完全相同。自知已经可以成立，体验仍然有它独有的内容。<a class=\"link-ref\" href=\"#ref-cwg\">[1]</a></p>\n<p>以善意为例。一个人理解何为善意，也清楚自己愿意帮助别人，这份认识是真实的。当他亲身经历一次帮助，感受到对方的处境、自己的选择和关系中的回应时，他又以一种具体方式认识了善意。前一份知晓没有被否定，后一份体验也不只是重复一句定义。</p>\n<figure class=\"origin-figure origin-figma-figure\"><div class=\"eyebrow\">同一种善意 · 两类认识</div><div class=\"origin-concept-grid origin-two\"><img src=\"/assets/origin-dao-20261105/knowing.svg\" width=\"368\" height=\"258\" loading=\"lazy\" decoding=\"async\" alt=\"知晓：理解并知道自己具有善意\"><img src=\"/assets/origin-dao-20261105/experiencing.svg\" width=\"368\" height=\"258\" loading=\"lazy\" decoding=\"async\" alt=\"体验：亲历善意的具体意味\"></div><figcaption class=\"origin-caption\">知晓与体验可以相互丰富。这里比较认识的内容，不安排创造的步骤。</figcaption></figure>\n<p>这个日常例子帮助我们看清两类认识，却不直接证明源头如何存在。回到《与神对话》的叙事，源头已经知晓自身，而它所向往的，是自身丰富性的充分认识。这样，“认识我是谁”就不必被理解为寻找一项遗漏的知识，也不必以否定原有觉知为起点。</p>\n<p>因而，讲到源头的欲望，我们需要保留它的深度：它不只是在询问一个名称或接受一条关于自己的定义。它所指向的，是对自身存在的充分认识。知晓与体验的区别，让这个意愿变得可以理解；而体验如何可能、如何具体发生，是随后才要展开的问题。</p>\n<p>这也帮助我们理解“我是谁”所包含的分量。对于一个具体的人，回答这个问题，往往会涉及性格、身份、关系和经历；对于源头，问题指向全部存在自身。它无法靠与整体之外的某物比较来获得定义。于是，这个愿望本身已经提出一个深远的问题：整体如何认识它自身的丰富？我们先把这个问题看清，再逐步讨论它的展开。</p>\n\n<h3>有所欲，是否意味着有所缺？</h3>\n<p>我们通常在缺少某种东西时产生欲望：饥饿时渴望食物，孤独时渴望陪伴。因此，一听到“源头有欲望”，很容易想到它是否也缺少了某种东西，必须从外部取得补偿，才能变得完整。</p>\n<p>可是，“一切万有”的前提正是：<strong>没有什么在源头之外。</strong>它无法依靠一个外部事物补全自己，因为所有可能被谈及的事物都已属于整体。在这个意义上，源头的完整不依赖外界的供给，也不等待某个他者认可它的存在。</p>\n<p>《与神对话》与《与神合一》对需要与欲望的区分，帮助我们理解这一点。需要，涉及某种必须被补足的条件；欲望，可以是一个完整存在自身的意愿。无所需要，并不自动等于无所意愿。把欲望一概解释为匮乏，会使我们忽略愿意认识、愿意表达本身的意义。<a class=\"link-ref\" href=\"#ref-need\">[4]</a></p>\n<figure class=\"origin-figure origin-figma-figure\"><div class=\"eyebrow\">需要与欲望 · 两种不同的指向</div><div class=\"origin-concept-grid origin-two\"><img src=\"/assets/origin-dao-20261105/need.svg\" width=\"368\" height=\"258\" loading=\"lazy\" decoding=\"async\" alt=\"需要：以外部条件补足缺失\"><img src=\"/assets/origin-dao-20261105/desire.svg\" width=\"368\" height=\"258\" loading=\"lazy\" decoding=\"async\" alt=\"欲望：完整存在自身的意愿\"></div><figcaption class=\"origin-caption\">缺口与完整的圆是概念示意。在本篇的源头观中，认识自身的欲望不以外部补足为前提。</figcaption></figure>\n<p>例如，一个人愿意与朋友分享一段旋律，并不必然因为他缺少什么，也可能因为这段旋律值得被表达和共同感受。这个例子只说明：意愿的发生，不总要以缺失为前提。源头的原初欲望，则进一步指向自身——完整的存在，愿意充分认识自身。</p>\n<p>这里需要分清“完整”所指的层次。存在上的完整，说明没有外物能使源头成为更多的存在；认识与体验的丰富，则关乎自身的性质如何被知晓与亲历。前者不依赖外部补足，后者仍然可以成为意愿所指向的内容。这是本篇借助《与神对话》所采用的解释。</p>\n<p>因此，“源头有欲”并不要求我们把人的焦虑、争夺或不满足投射到源头之上。人的欲望常常同时包含需要、习惯与自由的意愿；源头的原初欲望，在这里有更明确的含义：它是存在指向自身的意愿。将这层含义说清楚，才能理解一个本自具足的源头，何以仍有认识自身的愿望。</p>\n\n<h3>从源头，走向后面的追问</h3>\n<p>至此，本篇确立了两个认识：<strong>道，是具有宇宙性觉知与创造性的源头；源头最根本的欲望，是认识我是谁。</strong>前者说明它的本质以及它与万物的关系，后者让我们第一次触及它内在的原初意愿。</p>\n<p>欲望为后续的追问提供方向，但它本身还不是实现的步骤。“认识我是谁”指出意愿所向；“如何通过体验认识自身”才开始讨论途径。我们在这里借知晓与体验的区别理解这一意愿，将具体的创造、分化与体验机制留待后续章节展开。</p>\n<p>下一篇“一：混沌”，先从未分化的整体与潜能继续。此后再讨论差异与关系如何形成，丰富的世界如何展开。贯穿这些问题的那条线索，已经在源头处出现：一个包含一切的存在，具有认识自身的原初意愿。</p>\n</section>\n\n<details class=\"action-fold dao-fold dao-sources\" id=\"sources\"><summary>原文与出处</summary><div class=\"action-prose\">\n<p>正文以《三道哲学》的语言组织论述。“根源性、觉知性、创造性”以及两部分的章节结构，属于本篇的综合阐释；日常例子用于解释概念。</p>\n<ol class=\"source-list\">\n<li id=\"ref-cwg\"><strong>[1] 尼尔·唐纳德·沃尔什，《与神对话》第一卷。</strong><p>参照其起源叙事中关于 All That Is（一切万有）、整体之外无他者，以及 Knowing 与 Experiencing 的讨论。“To Know Who I Am”在本篇用作原初意愿的概括。正文为中文转述，不将转述标作逐字引文。</p></li>\n<li id=\"ref-wuwai\"><strong>[2] 《朱子语类》卷六十三·中庸二。</strong><p>所录问答出现“其大无外，其小无内”这一措辞，并追溯《楚辞》“其小无内，其大无垠”。本篇保留前一措辞，借以体会整体与细微的关系。<a href=\"https://zh.wikisource.org/wiki/朱子語類/063\" target=\"_blank\" rel=\"noopener noreferrer\">查看原文</a>。</p></li>\n<li id=\"ref-dao\"><strong>[3] 《道德经》第二十五、四十二章。</strong><p>开篇引文与本源主线的经文沿用本页选定文字。道具有宇宙性觉知与创造性的主张，是《三道哲学》采用的本体论立场。</p></li>\n<li id=\"ref-need\"><strong>[4] 尼尔·唐纳德·沃尔什，《与神对话》第一卷、《与神合一》。</strong><p>参照需要与欲望、源头不依赖外物满足自身的论述。本文据此区分存在的完整与认识自身的意愿。</p></li>\n</ol></div></details>\n<details class=\"action-fold dao-fold dao-sources\"><summary>这一源头观，还需要回答什么？</summary><div class=\"action-prose\">\n<p>这是《三道哲学》采纳的哲学立场，宇宙性觉知尚不是获得科学验证的结论。经典之间的对读能够帮助澄清概念，不能代替对世界的具体解释。</p>\n<p>接下来仍需说明：源头的觉知与个体经验怎样相连；一个整体内部如何形成差异；知晓、体验与完整之间的关系，能否得到一致的解释。尤其不能在未加说明的情况下，把“全知”同时定义为一切体验已完成，又说源头尚待获得体验。</p>\n<p>这些问题值得继续追究。它们也为后续创造论划定了任务：把意愿如何展开讲清楚，而不以一个宏大的名称代替全部说明。</p>\n</div></details>\n</article></div></div>";
export const originDaoPage=()=>markup;

export function initOriginDao(root){
 const page=root.querySelector('[data-origin-dao]');if(!page)return ()=>{};
 const listeners=[];const on=(el,type,fn)=>{el.addEventListener(type,fn);listeners.push(()=>el.removeEventListener(type,fn));};

const $=s=>page.querySelector(s);
function group(selector,fn){page.querySelectorAll(selector).forEach(button=>on(button,'click',()=>{page.querySelectorAll(selector).forEach(b=>b.setAttribute('aria-pressed',String(b===button)));fn(Number(Object.values(button.dataset)[0]));}));}
const positions=[[3,9,32,66],[43,54,45,40],[75,1,22,24],[1,1,98,98]];
const windowNotes=['<strong>看见树，是认识一种具体形态。</strong><br>画面仍保留树之外的河流、山峦与星光。','<strong>把目光移向河流。</strong><br>流动的水呈现另一种面貌，整幅画的连续性始终保留。','<strong>将窗口移向星光。</strong><br>所关注的局部发生改变，共同背景仍在。','<strong>把局部放回同一幅画。</strong><br>树、水与星光彼此有别，又共同参与整体。'];
group('[data-window]',i=>{const f=$('#art-focus');['left','top','width','height'].forEach((k,n)=>f.style[k]=positions[i][n]+'%');f.style.boxShadow=i===3?'none':'0 0 0 900px #efeee8aa';$('#window-note').innerHTML=windowNotes[i];});
on($('#reveal-slider'),'input',e=>{const n=Number(e.target.value);$('#reveal-veil').style.opacity=String(1-n/100);$('#reveal-value').textContent=n+'%';});
const originNotes=[['道 · 具有觉知与创造性的源头','从存在的根本，理解觉知与创造的位置。这是1.1首先展开的内容。'],['一 · 尚未分化的混沌','还没有成为具体的万物，却具有形成万物的能力。1.2从这里解释潜能。'],['二 · 阴阳、差异与参照','整体之内出现此与彼，经验由此获得参照。1.3从差异与极性展开。'],['三 · 阴、阳、既阴又阳','阴、阳与既阴又阳构成“三”；整体不能被孤立的任一端穷尽。这一关系仍在1.3中解释。'],['万物 · 共同构成的丰富形态','阴、阳、既阴又阳共同构成万物，具体关系与变化使形态各不相同。']];
function chooseOrigin(i){page.querySelectorAll('[data-path]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.path)===i)));page.querySelectorAll('[data-origin-node]').forEach(n=>n.classList.toggle('active',Number(n.dataset.originNode)===i));const note=page.querySelector('#path-note');note.replaceChildren();const title=document.createElement('strong'),body=document.createElement('span');title.textContent=originNotes[i][0];body.textContent=originNotes[i][1];note.append(title,body);}
page.querySelectorAll('[data-path]').forEach(b=>on(b,'click',()=>chooseOrigin(Number(b.dataset.path))));
 const onReference=e=>{const a=e.target.closest('a.link-ref');if(!a)return;e.preventDefault();const d=page.querySelector('#sources');d.open=true;page.querySelector(a.getAttribute('href'))?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});};on(page,'click',onReference);
 return ()=>listeners.forEach(dispose=>dispose());
}
